"""Read-only specialty diagnostics; no order, freeze or rule mutations."""
import hashlib,json,math
VERSION='specialty-brains-v1'
SPECIALTIES={'Market Data':'Coverage and data reliability','Risk & Compliance':'Portfolio limits and circuit breakers','Paper Trader':'Queued execution and costs','Logger':'Ledger and provenance integrity','Supervisor':'Operational health and recovery','Performance Reviewer':'Outcome quality and research evidence'}
def build(context,knowledge):
    ps=context['positions'];opened=[p for p in ps if p['status']=='OPEN'];closed=[p for p in ps if p['status']=='CLOSED'];state=context['state'];rules=context['rules'];coverage=context['coverage'];pending=context['pending'];messages=context['messages']
    cost=sum(p['position_value'] for p in opened);risk=sum(p['planned_loss'] for p in opened)
    expected=rules['starting_balance']+sum(p['realized_pnl'] or 0 for p in closed)-cost
    def metric(label,value,note=''):return {'label':label,'value':value,'note':note}
    def check(label,ok,note=''):return {'label':label,'status':'UNKNOWN' if ok is None else 'PASS' if ok else 'REVIEW','note':note}
    def limit(label,used,cap):return check(label,used<=cap,f'{used:.2f} / {cap:.2f}; descriptive current utilisation, not approval for a new order.')
    feed=coverage['instruments'];failures=[i for i in feed if i['status']=='FEED_ERROR'];unknown=[i for i in feed if not i.get('last_bar')]
    known_review=[p for p in closed if p.get('followed_rules') in ('yes','no','partial') and p.get('review_status')=='reviewed']
    eligible=[p for p in closed if p.get('planned_loss',0)>0 and p.get('realized_pnl') is not None and math.isfinite(p['realized_pnl'])]
    wins=sum(p['realized_pnl']>0 for p in closed);net=sum(p['realized_pnl'] or 0 for p in closed)
    evidence={
      'Market Data':([metric('Observed instruments',len(feed)),metric('Provider errors',len(failures)),metric('Missing checkpoints',len(unknown)),metric('Requests used today',coverage['credits_used_today'],f"Cap {coverage['daily_request_cap']}; persisted UTC budget")], [check('No current provider-error flags',not failures),check('All symbols have a checkpoint',not unknown)],feed,['Check timestamps and market session before interpreting stale candles.','Health does not prove freshness; no new requests are made here.']),
      'Risk & Compliance':([metric('Open entry cost',cost),metric('Open planned loss',risk),metric('Daily realised P/L',context['daily_pnl']),metric('Peak drawdown',max(0,state['peak_equity']-state['equity']))],[limit('Position count',len(opened),rules['max_open_positions']),limit('Aggregate entry cost',cost,rules['max_portfolio_exposure']),limit('Aggregate planned loss',risk,rules['max_portfolio_planned_loss']),check('Daily-loss threshold not reached',context['daily_pnl']>-rules['daily_loss_stop']),check('Drawdown threshold not reached',state['peak_equity']-state['equity']<rules['drawdown_freeze'])],opened,['Actual order approval also rechecks sizing, cash, sector/group and correlation limits.','This preview never approves, rejects or resumes a trade; gap losses can exceed planned risk.']),
      'Paper Trader':([metric('Pending orders',len(pending)),metric('Open positions',len(opened)),metric('Recorded estimated costs',sum(p.get('estimated_costs',0) for p in ps),'Includes legacy records; zero historical cost is not evidence of free execution.')],[check('Queued orders have decision time',all(json.loads(p['payload']).get('queued_at') for p in pending)),check('Paper-only operation',True)],pending,['Later eligible openings, gap stops and estimated costs remain the active execution model.','No quote, broker order or new exit model is supplied by this page.']),
      'Logger':([metric('Ledger cash difference',state['cash']-expected),metric('Trades missing original context',context['missing_context']),metric('Audit records',context['audit_count'])],[check('Cash reconciles',abs(state['cash']-expected)<1e-6),check('Original context coverage complete',context['missing_context']==0,'Legacy missing context must stay missing; do not invent it.')],[],['Snapshots preserve approved lesson versions and evidence.','This is an accounting/context check, not a full forensic audit or backup-integrity test.']),
      'Supervisor':([metric('Scheduler running',context['scheduler']),metric('Frozen',state['frozen']),metric('Freeze reason',state.get('freeze_reason') or 'None'),metric('Last successful cycle',context['last_success'] or 'Unavailable')],[check('Scheduler thread active',context['scheduler']),check('Desk not frozen',not state['frozen'])],[],['Investigate health, coverage and freeze reasons together.','VM backup timers and off-server recovery are not independently verified by these diagnostics. No automatic remediation is added.']),
      'Performance Reviewer':([metric('Closed paper trades',len(closed)),metric('Net closed P/L',net),metric('Win rate %',wins/len(closed)*100 if closed else None),metric('Expectancy R',sum(p['realized_pnl']/p['planned_loss'] for p in eligible)/len(eligible) if eligible else None),metric('Reviewed adherence %',sum(p['followed_rules']=='yes' for p in known_review)/len(known_review)*100 if known_review else None),metric('Research runs',context['research_count'])],[check('Initial review sample collected',len(eligible)>=30,'30 eligible trades is a review milestone, not statistical proof.'),check('Closed trades reviewed',len(known_review)==len(closed) if closed else None)],context['weekly'],['Unknown reviews are excluded, not counted as disciplined.','Research and operational results are separate; no automatic strategy promotion or validated-edge claim.'])}
    reports=[]
    for role,(metrics,checks,detail,limits) in evidence.items():
        events=[{k:m[k] for k in ('ts','sender','recipient','type','status','reason')} for m in messages if role in (m['sender'],m['recipient']) or m['recipient']=='ALL'][:10]
        report={'role':role,'specialty':SPECIALTIES[role],'version':VERSION,'metrics':metrics,'checks':checks,'details':detail,'knowledge':knowledge.get(role,[]),'recent_events':events,'limitations':limits,'policy':'Descriptive specialty evidence. Existing strategy, execution, risk and research rules remain unchanged. No model fine-tuning or executable notes.'}
        report['context_hash']=hashlib.sha256(json.dumps(report,sort_keys=True).encode()).hexdigest()[:20];reports.append(report)
    return reports
